#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
Analytic vs Simulation temperature profile T(x) at a given time for 1D transient conduction.

Model (Dirichlet-Dirichlet on 0<x<L):
  T(0,t) = Th   (hot wall)
  T(L,t) = Tc   (cold wall)
  T(x,0) = Tc   (initially cold)

Series solution:
  T(x,t)=Tc + (Th-Tc)*(1 - x/L) - (2*(Th-Tc)/pi) * sum_{n=1..inf} (1/n) sin(n*pi*x/L) exp(-alpha*(n*pi/L)^2 t)

where alpha = k/(rho*cp).

This script:
- Computes T_analytic(x,t) at your probe locations
- Compares to your simulation values (optional)
- Saves a PNG plot and a CSV table

Run (defaults match your XML snippet):
  python analytic_vs_sim_Tx_dirichlet_1D.py

Override parameters:
  python analytic_vs_sim_Tx_dirichlet_1D.py --t 5 --L 0.01 --Th 90 --Tc 20 --k 0.6 --rho 1000 --cp 4182 --N 5000

Provide your own x and sim T values:
  python analytic_vs_sim_Tx_dirichlet_1D.py --x "0.001,0.0015,0.002" --Tsim "46.24,33.45,25.97"
"""

from __future__ import annotations
import argparse
from pathlib import Path
import numpy as np
import pandas as pd
import matplotlib.pyplot as plt


def parse_list(s: str) -> np.ndarray:
    # Accept comma or semicolon separated lists
    parts = [p.strip() for p in s.replace(";", ",").split(",") if p.strip()]
    return np.array([float(p) for p in parts], dtype=float)


def T_analytic_dirichlet_1d(x: np.ndarray, t: float, L: float, Tc: float, Th: float, alpha: float, N: int = 5000) -> np.ndarray:
    """
    1D transient conduction in 0<x<L with Dirichlet BCs:
      T(0,t)=Th, T(L,t)=Tc, IC: T(x,0)=Tc.
    """
    x = np.asarray(x, dtype=float)
    Delta = Th - Tc
    n = np.arange(1, N + 1, dtype=float)  # 1..N
    # Use broadcasting: (N, len(x))
    sin_term = np.sin(np.outer(n * np.pi / L, x))
    decay = np.exp(-alpha * (n * np.pi / L) ** 2 * t)[:, None]
    series = (sin_term * decay / n[:, None]).sum(axis=0)
    return Tc + Delta * (1 - x / L) - (2 * Delta / np.pi) * series


