    ap.add_argument("--Tc", type=float, default=20.0, help="Cold wall temperature at x=L and initial temperature [K]")
    ap.add_argument("--k", type=float, default=0.6, help="Thermal conductivity [W/(m*K)]")
    ap.add_argument("--rho", type=float, default=1000.0, help="Density [kg/m^3]")
